        check("real PackageManager inventory is available",a.apps.size()>=30);List<Maintenance.Item> inventory=a.maintenance.inventory("全部组件");check("maintenance scans installed and disabled components",inventory.size()>a.apps.size());check("Android core, original HOME and TV hardware are protected",a.maintenance.protectedPackage("com.android.systemui")&&a.maintenance.protectedPackage("com.mitv.tvhome")&&a.maintenance.protectedPackage("com.android.bluetooth"));
        for(String plan:new String[]{"com.android.systemui","com.xiaomi.mitv.camera","com.example.a;reboot"}){boolean rejected=false;try{a.maintenance.importPlan(plan);}catch(Exception e){rejected=true;}check("unsafe plan rejected: "+plan,rejected);}
        int columns=a.pref().getInt("gridColumns",4);try{LauncherPrefs.importSettings(a,"{\"values\":{\"gridColumns\":7,\"favorites\":[\"invalid;input\"]}}");check("invalid configuration rejected atomically",false);}catch(Exception e){check("invalid configuration rejected atomically",a.pref().getInt("gridColumns",4)==columns);}
        LauncherPrefs.importSettings(a,"{\"columns\":6,\"dock_apps\":[],\"hidden_apps\":[],\"reduced_motion\":true,\"module_cards\":true}");check("upstream configuration fields and empty dock import",a.pref().getInt("gridColumns",4)==6&&a.allPinnedPackages().isEmpty()&&a.pref().getBoolean("reducedMotion",false));String exported=LauncherPrefs.export(a).toString();check("export excludes ADB keys and module approvals",!exported.contains("private.key")&&!exported.contains("moduleDecision"));
